WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, key, v FROM carts LATERAL VIEW OUTER EXPLODE(attributes) e AS key, v), enriched AS (SELECT src.customer_id, src.created_at, src.coupon_codes, src.key, src.v, d.email, d.country FROM lines src LEFT JOIN customers d ON src.customer_id = d.id), joined AS (SELECT a.customer_id, a.coupon_codes, a.country, p.name FROM enriched a JOIN customers p ON a.customer_id = p.id), enriched_carts AS (SELECT src.*, p.age FROM joined src LEFT JOIN customers p ON src.customer_id <=> p.id) SELECT p.segment, src.country AS cart_country, COUNT(*) AS num_rows, SUM(src.age) AS total_age, GROUPING_ID() AS level_id FROM enriched_carts src JOIN customers p ON src.customer_id = p.id GROUP BY ROLLUP (p.segment, src.country) ORDER BY total_age DESC NULLS LAST
